/**
 * phaseDStructuralWalkCount, test-and-introspection accessor for the
 * engine's commit-path Phase-D STRUCTURAL-walk counter (issue #129,
 * part 2).
 *
 * The counter increments once per DERIVED entry the Phase-D structural
 * topo walk (`recomputeAffected`'s Phase-1/2 indegree BFS + Phase-3 Kahn
 * drain in `graph.ts`) drains, for this engine's lifetime. It is the
 * white-box seam the #129 remainder anticipated for the SECOND reduction:
 * #243 elided the Phase-4 recompute fixpoint for a fully-mirrored
 * wasm-backed graph but retained the topo walk above it purely for cycle
 * detection; part 2 elides that topo walk too on the commit hot path,
 * delegating cycle detection to the authoritative backend (its own §5.1
 * Phase-D is the single cycle authority inside `apply_commands`). Whether
 * the walk ran is NOT observable through the public §12 surface (the
 * published `Commit` is byte-identical, SPEC §17.6 option-(c)), so the
 * reduction is pinned here.
 *
 * The value is monotonic. Test code snapshots it before and after a
 * commit and asserts the DELTA:
 *
 *   - Pure-TS floor (no injected backend): the delta equals the number
 *     of affected deriveds the commit walked (the js-ssot engine owns the
 *     structural topo walk for ordering + cycle detection).
 *   - Wasm-backed graph with no `commit-metadata` derived: every derived
 *     is mirrored, the #129 part-2 reduction skips the topo walk wholesale
 *     on the commit hot path (the backend re-derives the sub-graph and is
 *     the single cycle authority), and the delta is 0.
 *
 * Usage (test-only):
 *
 *   import { phaseDStructuralWalkCount } from '@causl/client-ts/testing'
 *
 *   const before = phaseDStructuralWalkCount(g)
 *   g.commit('bump', (tx) => tx.set(a, 5))
 *   const after = phaseDStructuralWalkCount(g)
 *   expect(after - before).toBe(0) // fully-mirrored wasm graph
 *
 * The helper resolves the engine's testing-dispatch registry directly,
 * via a relative import into the `@causl/core` source tree. Adapter code
 * has no production use for this number, it lives here, behind the
 * testing seam, because the underlying counter is engine-internal
 * commit-path observability, not a contract surface.
 */

import type { Graph } from '@causl/client-ts'
import { lookupTestingDispatch } from '../../src/testing-dispatch.js'

/**
 * Returns the cumulative Phase-D structural-walk count for `graph`.
 *
 * @param graph - The handle returned by `createCausl` (or the outer
 *  facade `createCauslWasm` / `createCauslWasmSync` returns).
 * @returns The engine's lifetime Phase-D structural-walk count.
 * @throws Error when `graph` was not produced by `createCausl`.
 */
export function phaseDStructuralWalkCount(graph: Graph): number {
  return lookupTestingDispatch(graph).phaseDStructuralWalkCount()
}
