/**
 * phaseDDerivedWalkCount — test-and-introspection accessor for the
 * engine's commit-path Phase-D recompute-walk counter (issue #129).
 *
 * The counter increments once per DERIVED entry the Phase-D recompute
 * fixpoint (`recomputeAffected`'s Phase 4 in `graph.ts`) actually
 * iterates over, for this engine's lifetime. It is the white-box seam
 * issue #129's remainder asks for: the "thin TS API" runs the TS
 * Phase-D structural walk in lockstep with the authoritative Rust
 * `apply_commands` pipeline on the wasm path, and the #129 reduction
 * elides that redundant per-derived pass for a fully-mirrored
 * wasm-backed graph. Whether the walk ran is NOT observable through the
 * public §12 surface (the published `Commit` is byte-identical either
 * way — SPEC §17.6 option-(c)), so the reduction is pinned here.
 *
 * The value is monotonic. Test code snapshots it before and after a
 * commit and asserts the DELTA:
 *
 *   - Pure-TS floor (no injected backend): the delta equals the number
 *     of affected deriveds the commit recomputed (the js-ssot engine
 *     owns the structural walk).
 *   - Wasm-backed graph with no `commit-metadata` derived: every
 *     derived is mirrored, the #129 reduction skips the Phase-4 loop
 *     wholesale (the backend's own engine re-derives the sub-graph),
 *     and the delta is 0.
 *
 * Usage (test-only):
 *
 *   import { phaseDDerivedWalkCount } from '@causl/client-ts/testing'
 *
 *   const before = phaseDDerivedWalkCount(g)
 *   g.commit('bump', (tx) => tx.set(a, 5))
 *   const after = phaseDDerivedWalkCount(g)
 *   expect(after - before).toBe(0) // fully-mirrored wasm graph
 *
 * The helper resolves the engine's testing-dispatch registry directly,
 * via a relative import into the `@causl/core` source tree. Adapter
 * code has no production use for this number — it lives here, behind
 * the testing seam, because the underlying counter is engine-internal
 * commit-path observability, not a contract surface.
 */

import type { Graph } from '@causl/client-ts'
import { lookupTestingDispatch } from '../../src/testing-dispatch.js'

/**
 * Returns the cumulative Phase-D derived-walk count for `graph`.
 *
 * @param graph - The handle returned by `createCausl` (or the outer
 *  facade `createCauslWasm` / `createCauslWasmSync` returns).
 * @returns The engine's lifetime Phase-D derived-walk count.
 * @throws Error when `graph` was not produced by `createCausl`.
 */
export function phaseDDerivedWalkCount(graph: Graph): number {
  return lookupTestingDispatch(graph).phaseDDerivedWalkCount()
}
