/**
 * inputCellRawValue, test-and-introspection accessor for the RAW outer TS
 * input-cell byte (issue #129, write-SSOT cutover) — the engine's
 * `InputEntry.value`, NOT the adopter-facing `read()` (which resolves the
 * authoritative backend under rust-ssot).
 *
 * The AC2 release pin: under the write-cells gate the cell holds `null`
 * after its first gated write (the third retained copy per committed input
 * is released — the documented 2x floor is the backend's write-through
 * cache, which owns `read()` reference identity and the
 * `serializable: false` contract, plus the wasm slot). On the pure-TS
 * floor (and js-ssot / legacy artefacts / the commit-metadata shape) the
 * cell holds the committed value.
 *
 * Usage (test-only):
 *
 *   import { inputCellRawValue } from '@causl/client-ts/testing'
 *
 *   g.commit('bump', (tx) => tx.set(a, { big: payload }))
 *   expect(inputCellRawValue(g, 'a')).toBe(null)   // write-SSOT gate
 *   expect(g.read(a)).toEqual({ big: payload })    // adopter surface intact
 */

import type { Graph, NodeId } from '@causl/client-ts'
import { lookupTestingDispatch } from '../../src/testing-dispatch.js'

/**
 * Returns the raw outer TS input-cell value for `id` on `graph`.
 *
 * @param graph - The handle returned by `createCausl` (or the outer
 *  facade `createCauslWasm` / `createCauslWasmSync` returns).
 * @param id - The input's NodeId.
 * @returns The raw cell byte; `undefined` for unregistered / non-input ids.
 * @throws Error when `graph` was not produced by `createCausl`.
 */
export function inputCellRawValue(graph: Graph, id: NodeId): unknown {
  return lookupTestingDispatch(graph).inputCellRawValue(id)
}
