/**
 * phaseBCellPublishCount, test-and-introspection accessor for the engine's
 * commit-path Phase-B outer-cell publication counter (issue #129,
 * write-SSOT cutover).
 *
 * The counter increments once per staged write the commit pipeline
 * publishes onto an outer TS input cell (the `#994` fast-arm write in
 * `tx.set` plus each Phase-B publishing row), for this engine's lifetime.
 * It is the white-box seam pinning the Phase A-C publication deletion:
 * under the write-cells gate (rust-ssot + the causl/causl-core-rs#320-era
 * artefact capability conjunction + no `commit-metadata` derived) the
 * staged writes are NEVER published onto the TS cells — the engine and the
 * backend's write-through value cache own the committed values — so the
 * per-commit delta is 0. The public surface is byte-identical either way
 * (that is the point), so the deletion is pinned here.
 *
 * Usage (test-only):
 *
 *   import { phaseBCellPublishCount } from '@causl/client-ts/testing'
 *
 *   const before = phaseBCellPublishCount(g)
 *   g.commit('bump', (tx) => tx.set(a, 5))
 *   expect(phaseBCellPublishCount(g) - before).toBe(0) // write-SSOT gate
 */

import type { Graph } from '@causl/client-ts'
import { lookupTestingDispatch } from '../../src/testing-dispatch.js'

/**
 * Returns the cumulative Phase-B outer-cell publication count for `graph`.
 *
 * @param graph - The handle returned by `createCausl` (or the outer
 *  facade `createCauslWasm` / `createCauslWasmSync` returns).
 * @returns The engine's lifetime Phase-B cell-publication count.
 * @throws Error when `graph` was not produced by `createCausl`.
 */
export function phaseBCellPublishCount(graph: Graph): number {
  return lookupTestingDispatch(graph).phaseBCellPublishCount()
}
