/**
 * phaseFRingAppendCount, test-and-introspection accessor for the engine's
 * commit-path Phase-F ring-append counter (issue #129, commit-SSOT
 * cutover).
 *
 * The counter increments once per row the Phase-F history append pushes
 * onto the TS `commitHistory` ring, for this engine's lifetime. It is the
 * white-box seam pinning the THIRD #129 reduction: under the engine-owned
 * commitLog gate (rust-ssot mode + a causl/causl-core-rs#318 artefact + the
 * adopter's `commitHistoryCap` threaded onto the engine's eviction horizon
 * via SetCommitLogCap + no `commit-metadata` derived) the Phase-F ring
 * append is deleted wholesale. The engine's cap-bounded commit log is the
 * single storage; `commitLog`, its Phase-F.4 refresh, and
 * `stats().retainedCommits` re-source from it. Whether the append ran is
 * NOT observable through the public surface (the published `commitLog`
 * window is byte-identical, SPEC §17.6 option-(c)), so the deletion is
 * pinned here.
 *
 * The value is monotonic. Test code snapshots it before and after a
 * commit and asserts the DELTA:
 *
 *   - Pure-TS floor (and js-ssot / legacy artefacts / the commit-metadata
 *     shape): the delta is 1 per accepted commit at `commitHistoryCap > 0`.
 *   - Wasm-backed rust-ssot graph on a #318 artefact with no
 *     `commit-metadata` derived: the delta is 0.
 *
 * Usage (test-only):
 *
 *   import { phaseFRingAppendCount } from '@causl/client-ts/testing'
 *
 *   const before = phaseFRingAppendCount(g)
 *   g.commit('bump', (tx) => tx.set(a, 5))
 *   const after = phaseFRingAppendCount(g)
 *   expect(after - before).toBe(0) // engine-owned commitLog
 *
 * The helper resolves the engine's testing-dispatch registry directly,
 * via a relative import into the `@causl/core` source tree. Adapter code
 * has no production use for this number; it lives here, behind the
 * testing seam, because the underlying counter is engine-internal
 * commit-path observability, not a contract surface.
 */

import type { Graph } from '@causl/client-ts'
import { lookupTestingDispatch } from '../../src/testing-dispatch.js'

/**
 * Returns the cumulative Phase-F ring-append count for `graph`.
 *
 * @param graph - The handle returned by `createCausl` (or the outer
 *  facade `createCauslWasm` / `createCauslWasmSync` returns).
 * @returns The engine's lifetime Phase-F ring-append count.
 * @throws Error when `graph` was not produced by `createCausl`.
 */
export function phaseFRingAppendCount(graph: Graph): number {
  return lookupTestingDispatch(graph).phaseFRingAppendCount()
}
